def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    me = [h[0] for h in history]
    op = [h[1] for h in history]
    last_me = me[-1]
    last_opp = op[-1]

    oppD = sum(1 for x in op if x == 'D')

    run = 0
    for x in reversed(op):
        if x == 'D':
            run += 1
        else:
            break

    l10 = 10 if n > 10 else n
    d10 = sum(1 for x in op[-l10:] if x == 'D')

    l20 = 20 if n > 20 else n
    d20 = sum(1 for x in op[-l20:] if x == 'D')

    start = n - 20
    if start < 0:
        start = 0

    tol = 0
    pun = 0
    tol_tot = 0
    pun_tot = 0

    for i in range(n - 1):
        if me[i] == 'D':
            if op[i + 1] == 'C':
                tol_tot += 1
                if i >= start:
                    tol += 1
            else:
                pun_tot += 1
                if i >= start:
                    pun += 1

    if run >= 5:
        return 'D'

    if n >= 8 and oppD >= n - 1:
        return 'D'

    if n >= 15 and oppD * 10 >= n * 4 and d20 >= 6 and run <= 2:
        return 'D'

    if n >= 20 and oppD * 3 >= n and d20 >= 7 and run <= 2:
        return 'D'

    if d10 >= 7:
        return 'D'

    if last_opp == 'D':
        return 'C'

    if pun == 0 and tol > 0:
        if n <= 90 or tol >= 10:
            return 'D'

    if last_me == 'D' and last_opp == 'C' and tol == 0 and pun == 0:
        return 'C'

    if pun_tot == 0 and tol_tot == 0 and 35 <= n <= 85:
        if d10 == 0 and oppD <= 6:
            return 'D'

    return 'C'
